<?php
require __DIR__.'/bootstrap.php';
$pdo=db();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 if($action==='login'){$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$q=$pdo->prepare('SELECT id,password_hash FROM admins WHERE email=?');$q->execute([$email?:'']);$a=$q->fetch();if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];header('Location: admin.php');exit;}$error='Неверный email или пароль.';}
 elseif(!empty($_SESSION['admin_id'])){try{
  if($action==='logout'){unset($_SESSION['admin_id']);session_regenerate_id(true);header('Location: admin.php');exit;}
  if($action==='dish-save'){$id=(int)($_POST['id']??0);$category=(string)($_POST['category']??'');$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));$weight=trim((string)($_POST['weight']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_INT);$image=trim((string)($_POST['image_url']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;$featured=isset($_POST['featured'])?1:0;if(!$name||strlen($name)>120||!$price||$price<0||!preg_match('/^[a-z]+$/',$category)||!preg_match('/^(https:\/\/|\/)/',$image))throw new RuntimeException('Проверьте название, категорию, цену и HTTPS-ссылку на фото.');if($id){$q=$pdo->prepare('UPDATE dishes SET category=?,name=?,description=?,weight=?,price=?,image_url=?,featured=?,active=?,sort_order=? WHERE id=?');$q->execute([$category,$name,$desc,$weight,$price,$image,$featured,$active,$sort,$id]);}else{$q=$pdo->prepare('INSERT INTO dishes(category,name,description,weight,price,image_url,featured,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$category,$name,$desc,$weight,$price,$image,$featured,$active,$sort]);}$notice='Блюдо сохранено.';}
  elseif($action==='dish-delete'){$pdo->prepare('DELETE FROM dishes WHERE id=?')->execute([(int)$_POST['id']]);$notice='Блюдо удалено.';}
  elseif($action==='status'){$table=(string)($_POST['table']??'');$status=(string)($_POST['status']??'');$allowed=['orders'=>['new','confirmed','preparing','ready','completed','cancelled'],'bookings'=>['new','confirmed','completed','cancelled'],'reviews'=>['pending','published','hidden'],'contact_messages'=>['new','read','archived']];if(!isset($allowed[$table])||!in_array($status,$allowed[$table],true))throw new RuntimeException('Недопустимый статус.');$pdo->prepare('UPDATE '.$table.' SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$notice='Статус обновлён.';}
  elseif($action==='settings'){$keys=['site_name','meta_title','meta_description','hero_eyebrow','hero_title','hero_text','address','phone','hours','instagram'];foreach($keys as $key){$val=trim((string)($_POST[$key]??''));$pdo->prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value')->execute([$key,substr($val,0,500)]);}$notice='Настройки сайта сохранены.';}
 }catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Не удалось сохранить изменения.';error_log($ex->getMessage());}}
}
$logged=!empty($_SESSION['admin_id']);page_start('Управление сайтом — Tokyo Premium','Защищённая панель управления сайтом.');header_html();
if(!$logged): ?><main class="admin-login"><div class="kicker">Tokyo Premium · управление</div><h1 class="page-hero-title">Вход в панель</h1><?php if($error): ?><p class="form-status error"><?=e($error)?></p><?php endif ?><p>Создайте первую учётную запись командой <code>php setup_admin.php</code>, затем войдите здесь.</p><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="login"><label class="field">Email<input name="email" type="email" autocomplete="username" required></label><label class="field">Пароль<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Войти ↗</button></form></main><?php else:
$cats=$pdo->query('SELECT slug,name FROM categories ORDER BY sort_order')->fetchAll();$items=$pdo->query('SELECT * FROM dishes ORDER BY id DESC')->fetchAll();$orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 100')->fetchAll();$bookings=$pdo->query('SELECT * FROM bookings ORDER BY booking_date DESC,booking_time DESC LIMIT 100')->fetchAll();$reviews=$pdo->query('SELECT * FROM reviews ORDER BY id DESC LIMIT 100')->fetchAll();$contact_messages=$pdo->query('SELECT * FROM contact_messages ORDER BY id DESC LIMIT 100')->fetchAll();$statuses=['new'=>'Новая','confirmed'=>'Подтверждена','preparing'=>'Готовится','ready'=>'Готов','completed'=>'Завершена','cancelled'=>'Отменена','pending'=>'На модерации','published'=>'Опубликован','hidden'=>'Скрыт']; ?>
<main class="admin-shell"><div class="section-head"><div><div class="kicker">Tokyo Premium · управление</div><h1>Панель сайта</h1></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="logout"><button class="button secondary">Выйти</button></form></div><?php if($notice): ?><p class="form-status success"><?=e($notice)?></p><?php endif ?><?php if($error): ?><p class="form-status error"><?=e($error)?></p><?php endif ?>
<section class="admin-card"><h2>Позиции меню</h2><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="dish-save"><label>Название<input name="name" required maxlength="120"></label><label>Категория<select name="category"><?php foreach($cats as $c): ?><option value="<?=e($c['slug'])?>"><?=e($c['name'])?></option><?php endforeach ?></select></label><label>Цена, ₸<input name="price" type="number" min="0" required></label><label>Вес / объём<input name="weight" maxlength="30"></label><label>Порядок<input name="sort_order" type="number" value="0"></label><label>Фото HTTPS URL<input name="image_url" type="url" required></label><label class="field full">Описание<textarea name="description" maxlength="300"></textarea></label><label><input type="checkbox" name="active" checked> В меню</label><label><input type="checkbox" name="featured"> Выбор шефа</label><button class="button">Добавить блюдо</button></form><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Блюдо</th><th>Цена</th><th>Доступно</th><th>Действие</th></tr></thead><tbody><?php foreach($items as $d): ?><tr><td><strong><?=e($d['name'])?></strong><br><small><?=e($d['category'])?> · <?=e($d['weight'])?></small><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="dish-save"><input type="hidden" name="id" value="<?=$d['id']?>"><input name="name" value="<?=e($d['name'])?>" required><select name="category"><?php foreach($cats as $c): ?><option value="<?=e($c['slug'])?>" <?=$d['category']===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select><input name="price" type="number" min="0" value="<?=$d['price']?>"><input name="weight" value="<?=e($d['weight'])?>"><input name="sort_order" type="number" value="<?=$d['sort_order']?>"><input name="image_url" value="<?=e($d['image_url'])?>"><textarea name="description"><?=e($d['description'])?></textarea><label><input type="checkbox" name="active" <?=$d['active']?'checked':''?>> В меню</label><label><input type="checkbox" name="featured" <?=$d['featured']?'checked':''?>> Выбор шефа</label><button class="button">Сохранить</button></form></td><td><?=number_format((int)$d['price'],0,'.',' ')?> ₸</td><td><?=$d['active']?'Да':'Нет'?></td><td><form method="post" onsubmit="return confirm('Удалить блюдо?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="dish-delete"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="danger">Удалить</button></form></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="admin-card"><h2>Заявки и отзывы</h2><?php foreach(['orders'=>'Заказы','bookings'=>'Брони','reviews'=>'Отзывы','contact_messages'=>'Сообщения'] as $table=>$label): ?><h3><?=$label?></h3><table class="admin-table"><thead><tr><th>№</th><th>Гость / данные</th><th>Статус</th><th>Изменить</th></tr></thead><tbody><?php foreach($$table as $row): ?><tr><td>#<?=$row['id']?></td><td><?=e($row['customer_name']??$row['guest_name'])?><br><?=e($row['phone']??'')?><?=isset($row['total'])?'<br>'.number_format((int)$row['total'],0,'.',' ').' ₸':''?><?=isset($row['booking_date'])?'<br>'.e($row['booking_date'].' '.$row['booking_time'].' · '.$row['guest_count'].' гостей'.(!empty($row['zone'])?' · '.$row['zone']:'').(!empty($row['preferred_table'])?' · стол '.$row['preferred_table']:'')):''?><?=isset($row['body'])?'<br>'.e($row['body']):''?><?=isset($row['email'])?'<br>'.e($row['email']).'<br>'.e($row['subject']).'<br>'.e($row['message']):''?></td><td><?=e($statuses[$row['status']]??$row['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="table" value="<?=$table?>"><input type="hidden" name="id" value="<?=$row['id']?>"><select name="status"><?php $opts=$table==='orders'?array_intersect_key($statuses,array_flip(['new','confirmed','preparing','ready','completed','cancelled'])):($table==='bookings'?array_intersect_key($statuses,array_flip(['new','confirmed','completed','cancelled'])):($table==='contact_messages'?['new'=>'Новое','read'=>'Прочитано','archived'=>'В архиве']:array_intersect_key($statuses,array_flip(['pending','published','hidden'])))); foreach($opts as $key=>$value): ?><option value="<?=e($key)?>" <?=$row['status']===$key?'selected':''?>><?=e($value)?></option><?php endforeach ?></select><button class="button">Обновить</button></form></td></tr><?php endforeach ?></tbody></table><?php endforeach ?></section>
<section class="admin-card"><h2>Контакты и SEO</h2><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="settings"><?php foreach(['site_name'=>'Название сайта','meta_title'=>'SEO title','meta_description'=>'SEO description','hero_eyebrow'=>'Надзаголовок первого экрана','hero_title'=>'Заголовок первого экрана','hero_text'=>'Текст первого экрана','address'=>'Адрес','phone'=>'Телефон','hours'=>'График','instagram'=>'Instagram URL'] as $key=>$label): ?><label><?=$label?><?php if(in_array($key,['meta_description','hero_text'],true)): ?><textarea name="<?=$key?>" maxlength="500"><?=e(setting($key))?></textarea><?php else: ?><input name="<?=$key?>" value="<?=e(setting($key))?>" maxlength="500"><?php endif ?></label><?php endforeach ?><button class="button">Сохранить настройки</button></form></section></main>
